// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

contract MLInferenceServer is AccessControl {
    using ECDSA for bytes32;

    bytes32 public constant MODEL_ADMIN = keccak256("MODEL_ADMIN");
    bytes32 public constant INFERENCE_RUNNER = keccak256("INFERENCE_RUNNER");
    bytes32 public constant MODEL_UPLOADER = keccak256("MODEL_UPLOADER");

    struct ModelMetadata {
        bytes32 contentHash;
        uint256 fileSize;
        string modelType;
        address uploader;
        uint256 timestamp;
        bool verified;
    }

    struct UploadSession {
        address initiator;
        uint256 chunkCount;
        uint256 chunksReceived;
        bytes32 expectedHash;
        uint256 maxFileSize;
        bool finalized;
        mapping(uint256 => bytes32) chunkHashes;
    }

    uint256 public constant MAX_MODEL_SIZE = 100 * 1024 * 1024; // 100MB
    string[] public ALLOWED_MODEL_TYPES;

    mapping(bytes32 => ModelMetadata) public models;
    mapping(uint256 => UploadSession) public sessions;
    mapping(address => uint256) public uploadNonces;
    uint256 private sessionCounter;

    event ModelUploaded(bytes32 indexed modelId, address indexed uploader, string modelType);
    event UploadSessionCreated(uint256 indexed sessionId, address indexed initiator);
    event ChunkUploaded(uint256 indexed sessionId, uint256 chunkIndex);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MODEL_ADMIN, msg.sender);
        ALLOWED_MODEL_TYPES.push("onnx");
        ALLOWED_MODEL_TYPES.push("tensorflow");
        ALLOWED_MODEL_TYPES.push("pytorch");
    }

    function _validateModelType(string memory modelType) internal view returns (bool) {
        for (uint i = 0; i < ALLOWED_MODEL_TYPES.length; i++) {
            if (keccak256(bytes(ALLOWED_MODEL_TYPES[i])) == keccak256(bytes(modelType))) {
                return true;
            }
        }
        return false;
    }

    function initiateUploadSession(
        uint256 chunkCount,
        bytes32 expectedHash,
        uint256 totalFileSize,
        string calldata modelType
    ) external returns (uint256) {
        require(hasRole(MODEL_UPLOADER, msg.sender) || hasRole(MODEL_ADMIN, msg.sender),
            "Unauthorized: requires MODEL_UPLOADER or MODEL_ADMIN role");
        require(totalFileSize <= MAX_MODEL_SIZE, "File exceeds maximum size");
        require(chunkCount > 0 && chunkCount <= 1000, "Invalid chunk count");
        require(_validateModelType(modelType), "Unsupported model type");

        uint256 sessionId = sessionCounter++;
        UploadSession storage session = sessions[sessionId];
        session.initiator = msg.sender;
        session.chunkCount = chunkCount;
        session.expectedHash = expectedHash;
        session.maxFileSize = totalFileSize;
        session.finalized = false;

        emit UploadSessionCreated(sessionId, msg.sender);
        return sessionId;
    }

    function uploadChunk(
        uint256 sessionId,
        uint256 chunkIndex,
        bytes32 chunkHash,
        bytes calldata signature
    ) external {
        UploadSession storage session = sessions[sessionId];
        require(!session.finalized, "Session already finalized");
        require(chunkIndex < session.chunkCount, "Invalid chunk index");
        require(session.chunkHashes[chunkIndex] == bytes32(0), "Chunk already uploaded");

        // Verify the chunk upload is authorized by session initiator
        bytes32 message = keccak256(abi.encodePacked(
            sessionId, chunkIndex, chunkHash, uploadNonces[session.initiator]
        ));
        bytes32 ethSignedMessage = message.toEthSignedMessageHash();
        address signer = ethSignedMessage.recover(signature);

        // Authorization check: signer must be the session initiator
        require(
            signer == session.initiator,
            "Signature must be from session initiator"
        );

        session.chunkHashes[chunkIndex] = chunkHash;
        session.chunksReceived++;

        emit ChunkUploaded(sessionId, chunkIndex);
    }

    function finalizeUpload(
        uint256 sessionId,
        string calldata modelType,
        bytes32 modelId
    ) external {
        UploadSession storage session = sessions[sessionId];
        require(msg.sender == session.initiator, "Only initiator can finalize");
        require(!session.finalized, "Already finalized");
        require(session.chunksReceived == session.chunkCount, "Not all chunks uploaded");
        require(_validateModelType(modelType), "Invalid model type");
        // Prevent overwriting an existing model record (including verified models)
        require(models[modelId].contentHash == bytes32(0), "Model ID already exists");

        // Compute aggregate hash from chunks
        bytes32 aggregateHash = _computeAggregateHash(sessionId, session.chunkCount);
        require(aggregateHash == session.expectedHash, "Hash mismatch");

        models[modelId] = ModelMetadata({
            contentHash: aggregateHash,
            fileSize: session.maxFileSize,
            modelType: modelType,
            uploader: msg.sender,
            timestamp: block.timestamp,
            verified: false
        });

        session.finalized = true;
        uploadNonces[msg.sender]++;

        emit ModelUploaded(modelId, msg.sender, modelType);
    }

    function _computeAggregateHash(uint256 sessionId, uint256 chunkCount) internal view returns (bytes32) {
        bytes32 result = bytes32(0);
        for (uint256 i = 0; i < chunkCount; i++) {
            result = keccak256(abi.encodePacked(result, sessions[sessionId].chunkHashes[i]));
        }
        return result;
    }

    function verifyModel(bytes32 modelId) external onlyRole(MODEL_ADMIN) {
        require(models[modelId].contentHash != bytes32(0), "Model does not exist");
        models[modelId].verified = true;
    }

    function addAllowedModelType(string calldata modelType) external onlyRole(MODEL_ADMIN) {
        ALLOWED_MODEL_TYPES.push(modelType);
    }

    function grantUploaderRole(address account) external onlyRole(MODEL_ADMIN) {
        _grantRole(MODEL_UPLOADER, account);
    }

    function revokeUploaderRole(address account) external onlyRole(MODEL_ADMIN) {
        _revokeRole(MODEL_UPLOADER, account);
    }
}
